      "title": "ಕ್ಯಾಟಲ್ ಇನ್ ರೀಪೋಸ್",
      "title_raw": "LXV-23, ಕ್ಯಾಟಲ್ ಇನ್ ರೀಪೋಸ್",
      "meta": "1877, ಇಂಗ್ಲೆಂಡ್, ಥಾಮಸ್ ಸಿಡ್ನಿ ಕೂಪರ್ ಆರ್ಎ ಅವರಿಂದ ಬಿಡಿಸಲಾದ ವರ್ಣಚಿತ್ರ",
      "paras": [
        "'ಕ್ಯಾಟಲ್ ಇನ್ ರೀಪೋಸ್' (ವಿಶ್ರಾಂತಿಯಲ್ಲಿರುವ ಜಾನುವಾರುಗಳು). ವಿಶ್ರಾಂತಿ ಪಡೆಯುತ್ತಿರುವ ಜಾನುವಾರುಗಳು, ಕುರಿಗಳು ಮತ್ತು ಹಸುಗಳು. ಹಸುಗಳು ನೆಲದ ಮೇಲೆ ಮಲಗಿರುವುದು ಕಂಡುಬಂದರೆ, ಈ ಪ್ರಕೃತಿ ದೃಶ್ಯಾವಳಿಯಲ್ಲಿ ಕುರಿಗಳು ಅಲ್ಲಲ್ಲಿ ನಿಂತಿವೆ. ಬಿರುಗಾಳಿಯ ವಾತಾವರಣವನ್ನು ಮೋಡಗಳು ಪ್ರತಿಬಿಂಬಿಸುತ್ತಿರುವ ಆಕಾಶದತ್ತ ಕುರಿಗಳು ನೋಡುತ್ತಿವೆ. ಮಲಗಿರುವ ಹಸುವಿನ ದೇಹದ ಮೇಲಿನ ಸಣ್ಣ ರೋಮಗಳು ಜೀವಂತ ಹಸುವಿನಷ್ಟೇ ನೈಜವಾಗಿ ಕಾಣುತ್ತವೆ ಮತ್ತು ವೀಕ್ಷಕರು ಯಾವ ಮೂಲೆಯಲ್ಲಿನಿಂತರೂ, ಈ ಪ್ರಾಣಿಯ ಕಣ್ಣುಗಳು ತ್ರಿಮಾತ್ರೀಯ (3D) ಪರಿಣಾಮದೊಂದಿಗೆ ಅತ್ಯಂತ ಸ್ಪಷ್ಟವಾಗಿ ಅವರನ್ನೇ ನೋಡುವಂತೆ ಭಾಸವಾಗುತ್ತದೆ. ತಮ್ಮ ಹೆಚ್ಚಿನ ಕಲಾಕೃತಿಗಳಲ್ಲಿ ಪ್ರಾಣಿಗಳ ನಿರೂಪಣೆಯೊಂದಿಗೆ ಇರುವ ಪ್ರಕೃತಿ ದೃಶ್ಯಾವಳಿಯು ಈ ವರ್ಣಚಿತ್ರಕಾರರ ನೆಚ್ಚಿನ ವಿಷಯವಾಗಿದೆ. ಈ ವರ್ಣಚಿತ್ರಕಾರರ ಕಾಲ ಕ್ರಿ.ಶ. ಹತ್ತೊಂಬತ್ತನೇ ಶತಮಾನದ ಉತ್ತರಾರ್ಧದದಾಗಿದೆ. ಅವರ ವರ್ಣಚಿತ್ರಗಳ ಯಾವುದೇ ಮೂಲೆಯಲ್ಲೂ ಕುರಿ ಅಥವಾ ಹಸುಗಳು ಕಂಡುಬರುತ್ತವೆ. ಈ ಕಲಾಕೃತಿಯನ್ನು ಒಮ್ಮೆ 'ರಾಯಲ್ ಅಕಾಡೆಮಿ ಆಫ್ ಆರ್ಟ್ಸ್'ನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಲಾಗಿತ್ತು."
      ],
