      "meta": "1877, ଇଂଲଣ୍ଡ, ଥୋମାସ ସିଡନୀ କୁପର ଆରଏଙ୍କ ଦ୍ୱାରା",
      "paras": [
        "ଏହି ମନୋରମ ତୈଳଚିତ୍ରଟିର ନାମ 'ବିଶ୍ରାମରେ ଗୋପଶୁ' (Cattle in Repose)। ଏଥିରେ ଏକ ବିସ୍ତୃତ ପ୍ରାକୃତିକ ଦୃଶ୍ୟାବଳୀ ମଧ୍ୟରେ ଗୋରୁ ଓ ମେଣ୍ଢାମାନେ ବିଶ୍ରାମ ନେଉଥିବାର ଦୃଶ୍ୟାୟିତ ହୋଇଛି। କେତେକ ଗାଈ ଭୂମିରେ ବସି ରହିଥିବା ବେଳେ ଏଣେତେଣେ ମେଣ୍ଢାଗୁଡ଼ିକ ଛିଡ଼ା ହୋଇଛନ୍ତି। ମେଣ୍ଢାଗୁଡ଼ିକ ଆକାଶ ଆଡ଼କୁ ଅନାଇଛନ୍ତି, ଯେଉଁଠି ଘନ ମେଘମାଳା ଏକ ଆସନ୍ନ ଝଡ଼ର ସୂଚନା ଦେଉଛି। ଚିତ୍ରପଟରେ ବସିଥିବା ଗାଈଟିର ଶରୀରରେ ଥିବା ସୂକ୍ଷ୍ମ ଲୋମଗୁଡ଼ିକ ଏକ ଜୀବନ୍ତ ପଶୁ ଭଳି ଅତ୍ୟନ୍ତ ସ୍ୱାଭାବିକ ମନେହୁଏ। ଏହାର ଥ୍ରୀ ଡି ପ୍ରଭାବ ଏପରି ଯେ, ଦର୍ଶକ ଗ୍ୟାଲେରୀର ଯେଉଁ କୋଣରେ ଛିଡ଼ା ହେଲେ ମଧ୍ୟ ଗାଈଟି ସିଧାସଳଖ ତାଙ୍କୁ ହିଁ ଚାହିଁଥିବା ପରି ପ୍ରତୀୟମାନ ହୁଏ। ୧୯ଶ ଶତାବ୍ଦୀର ଶେଷ ଭାଗର ଏହି ଶିଳ୍ପୀଙ୍କ ପ୍ରିୟ ବିଷୟବସ୍ତୁ ଥିଲା ପ୍ରକୃତି ଓ ପଶୁପକ୍ଷୀଙ୍କ ଚିତ୍ରାଙ୍କନ। ତାଙ୍କର ପ୍ରାୟ ପ୍ରତ୍ୟେକ କୃତିରେ ଗୋରୁ କିମ୍ବା ମେଣ୍ଢାଙ୍କ ଉପସ୍ଥିତି ଦେଖିବାକୁ ମିଳେ। ଲଣ୍ଡନର ପ୍ରସିଦ୍ଧ 'ରୋୟାଲ୍ ଏକାଡେମୀ ଅଫ୍ ଆର୍ଟ'ରେ ଏକଦା ପ୍ରଦର୍ଶିତ ହୋଇଥିବା ଏହି ଆଲେଖ୍ୟଟି ଶିଳ୍ପୀଙ୍କ ସୂକ୍ଷ୍ମ ନିପୁଣତାର ଏକ ଶ୍ରେଷ୍ଠ ନିଦର୍ଶନ।"
      ],
