      "meta": "1884, फ्रान्स, बाय डब्ल्यू. ए. बोगुएरो",
      "paras": [
        "मिलेटसची कन्या असलेल्या 'बिब्लिस' या अप्सरेचे हे एक प्रभावी चित्र आहे. बिब्लिस तिच्या जुळ्या भावाच्या, कॉनसच्या प्रेमात पडली. हे चित्र जमिनीवर बसलेल्या एका नग्न स्त्रीचे आहे, जी तिचे कोपर जमिनीवर टेकवून खाली जमिनीकडे पाहत आहे. डाव्या बाजूला वरच्या कोपऱ्यात 'W.A. Bouguereau -1884' असे कोरलेले आहे.बोग्वेरो यांनी रेखाटलेले हे बिब्लिसचे अप्रतिम चित्र संग्रहालयाची एक मौल्यवान संपत्ती आहे. प्रसिद्ध फ्रेंच चित्रकार बोग्वेरो हे स्त्री सौंदर्याचे उत्तम सादरीकरण, चित्रांमधील कमालीचा गुळगुळीतपणा आणि आकृत्यांच्या उत्कृष्ट डौलदारपणासाठी प्रशंसनीय होते. त्यांच्या परिपक्व वर्षांतील निर्मिती असलेले संग्रहालयातील हे बिब्लिसचे चित्र स्वाक्षरी आणि दिनांकित (1884) आहे. ही उत्कृष्ट कलाकृती बिब्लिस या अप्सरेच्या जीवनातील एका निर्णायक क्षणाची नोंद करते. क्रीटच्या मिलेटसची मुलगी बिब्लिस, कथेनुसार तिच्या जुळ्या भावाच्या, कॅमसच्या प्रेमात पडली. मात्र, त्याने तिच्या प्रेमाला प्रतिसाद न दिल्याने तो तिच्यापासून दूर पळून गेला. त्याच्यावरील आपल्या दुर्दैवी प्रेमावर नियंत्रण ठेवता न आल्याने बिब्लिस एका पर्वताच्या शिखरावरून उडी मारून आपले जीवन संपवण्याचा प्रयत्न करते. परंतु, इतर अप्सरांना तिच्या दुर्दशेची दया येते आणि त्या तिला अमर करून 'हॅमाड्रेड' या नावाने त्यांच्या समाजात स्वीकारतात. तरीही, दुसऱ्या एका कथेनुसार, पळून जाणाऱ्या आपल्या भावाचा पाठलाग करून पूर्णपणे थकलेली बिब्लिस \"दुःखाच्या प्रवाहात जमिनीवर कोसळली आणि त्वरित एका कारंज्यामध्ये रूपांतरित झाली\". ही कथा आणि तिच्या नीतिमत्तेपेक्षा आपण बिब्लिसच्या अवर्णनीय सौंदर्याने अधिक भारावून जातो. अत्यंत सुंदरपणे रेखाटलेले शरीर आपले लक्ष वेधून घेते. उबदार सोनेरी रंगाच्या त्वचेचे संवेदनशील स्वरूप दुर्मिळ कौशल्याने व्यक्त केले आहे. ही आकृती प्रशंसनीयपणे रेखाटलेली असून तिला वैज्ञानिक अचूकतेसह पूर्णत्वास नेले आहे."
      ],
