      "title": "स्टिल लाईफ",
      "title_raw": "LXVI-4, स्टिल लाईफ",
      "meta": "1860-1870, फ्रान्स-चार्डिन (जीन-बॅप्टिस्ट शिमोन चार्डीन)",
      "paras": [
        "वर्णन केलेल्या या कलाकृतीचे शीर्षक \"स्टिल लाइफ\" किंवा \"स्टिल लाइफ विथ अ डिअर अँड बर्ड्स\" असे असून ती 18 व्या शतकातील फ्रेंच चित्रकार जीन-सिमियन चार्डिन यांनी रेखाटली आहे. यात स्वयंपाकघराच्या पार्श्वभूमीवर शिकार केलेल्या मृत पक्ष्यांचा आणि एका हरणाचा ढीग, तसेच शिकारीची साधने दर्शविली आहेत. खिडकीतून बाहेर पाहणारा एक मुलगा या शिकार केलेल्या प्राण्यांचे निरीक्षण करताना दाखवला आहे. संग्रहालयातील चार्डिन यांचे हे विशाल तैलचित्र स्वयंपाकघरात इकडे तिकडे विखुरलेली शिकार दर्शवते. खिडकीच्या उंबरठ्यावर बसलेला एक मुलगा या लुटीकडे आनंदाने पाहत आहे. शिकार केलेले प्राणी आणि पक्षी भांडी, वाडगे आणि ताटांमध्ये मिसळून अव्यवस्थित पडलेले आहेत. आधीच भरलेली ही खोली शिकारीची साधने- बिगुल, भोंगा, दोऱ्या इत्यादींनी अधिकच भरलेली दिसते. हे जडत्व नैसर्गिक वाटण्याबरोबरच, वस्तूंवर पडणाऱ्या प्रकाशाचे सुंदर परिणाम आणि त्यांची अभ्यासपूर्ण मांडणी यामुळे सुसह्य होते."
      ],
      "imgSrc": "images/painting_gallery-item6.png",
